// #2a8411 מסך ניהול משתמשים בחברה — משתמש רגיל не получает доступ (AC5). Кейс: .qa/tests/company-users/CU-06.
// Только просмотр. USER = «QA Member 2» — его данные и роль не трогаем.
import { test, expect, Page } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import { ACCOUNT_ADMINS_ONLY, NO_PERMISSION } from './users-page';

async function openAccountMenu(page: Page) {
  await page.goto('/');
  const nav = page.getByRole('navigation', { name: 'ניווט ראשי' });
  await nav.getByRole('button', { name: 'חשבון', exact: true }).click();
  await expect(nav.getByRole('button', { name: 'יציאה', exact: true })).toBeVisible();
  return nav;
}

test.describe('משתמשי החברה — משתמש רגיל', () => {
  test.use({ storageState: authState('user') });

  for (const route of ['/users', '/users/invite']) {
    test(`${route}: משתמש רגיל רואה "אין לך הרשאה למסך זה" #2a8411 @desktop @prod-safe`, async ({ page }) => {
      await page.goto(route);
      const main = page.getByRole('main');
      await expect(main.getByText(NO_PERMISSION, { exact: true })).toBeVisible();
      await expect(main.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toBeVisible();
      await expect(main.getByRole('link', { name: 'חזרה לדף הבית' })).toBeVisible();
      // Содержимого экрана нет.
      await expect(main.getByRole('table')).toHaveCount(0);
      await expect(main.getByRole('link', { name: 'הזמנת משתמש חדש' })).toHaveCount(0);
      await expect(main.getByRole('button', { name: 'עריכה' })).toHaveCount(0);
      await expect(main.getByRole('textbox', { name: 'אימייל *' })).toHaveCount(0);
      await expect(main.getByRole('heading', { name: /^(משתמשי החברה|הזמנת משתמש חדש)$/ })).toHaveCount(0);
    });
  }

  test('משתמש רגיל: אין "משתמשי החברה" ו"הזמנת משתמש חדש" בתפריט חשבון #2a8411 @desktop @prod-safe', async ({ page }) => {
    const nav = await openAccountMenu(page);
    await expect(nav.getByRole('link', { name: 'משתמשי החברה' })).toHaveCount(0);
    await expect(nav.getByRole('link', { name: 'הזמנת משתמש חדש' })).toHaveCount(0);
  });
});

// Контроль: у מנהל חשבון те же пункты есть — проверка выше не пустая.
test.describe('משתמשי החברה — מנהל חשבון (בקרה)', () => {
  test.use({ storageState: authState('admin') });

  test('מנהל חשבון: "משתמשי החברה" ו"הזמנת משתמש חדש" בתפריט חשבון #2a8411 @desktop @prod-safe', async ({ page }) => {
    const nav = await openAccountMenu(page);
    await expect(nav.getByRole('link', { name: 'משתמשי החברה', exact: true })).toHaveAttribute('href', '/users');
    await expect(nav.getByRole('link', { name: 'הזמנת משתמש חדש', exact: true })).toHaveAttribute('href', '/users/invite');
  });
});
